const cecWvr=(F,prev)=>{/* pkgWVR rev 5: a verse the side withdrew or stopped resting on in round 2 or 3 is cited again in its close as a footing of the side's own link; the enforcer decides. Withdrawn: "I [now|therefore|...] withdraw/drop/set aside/retract <verses>", "I do not / no longer rest ... on <verses>", "<verses>: withdrawn", "<verses> stay withdrawn"; each verse of a list or range; "it"/"them" takes the verses of its own clause, or of the clause before when its own clause is bare ("...; I withdraw it."), or of the sentence before when at most six words and no quotation stand before "I" in its own sentence; a verse list "Matthew 1:18, 20" holds verse 20; a verse named only as the place of a clause, phrase, word or reading is not taken. Not withdrawn: inside a quotation; a clause opened by if, unless or provided ("And"/"But"/"Even" may lead; not "If anything"); "if I withdraw"; "asks that I withdraw"; a condition after the verse; a partial withdrawal ("alone", "by itself", "only as"); a list verse that "stays". Footing in the close: "layer of"/"footing of" with the verse in that clause, "stands on"/"rests on" with the verse after the verb and no "not" between; not in a question, not where the opponent says it or is the subject, not on the opponent's link only. A book name matches its own prefix or a common short form; a bare "1:20" takes the book before it on the line, else any book. Manual: pkgWVR section. */
 const out=[],st=x=>x.replace(/[*_]+/g,'').replace(/^[\s>#-]+/,'').trim(),SE=/(?<=[.!?]["”’')\]*_]*)(?<!\b[A-Z][a-z]{1,4}\.)\s+|(?<=\b[A-Z][a-z]{1,4}\.)\s+(?!\d)/,nq=x=>st(x).replace(/\s+/g,' ').toLowerCase();let k=Math.max(0,...prev.map(c=>+String(c.id).slice(1)||0));
 const R1='(?:[1-3]\\s+)?[A-Z][a-z]+\\.?\\s+\\d+:\\d+(?:[-–]\\d+)?|\\d+:\\d+(?:[-–]\\d+)?',LIST='(?:'+R1+')(?:\\s*(?:,\\s*(?:and\\s+)?|\\s+and\\s+)(?:'+R1+'))*',CR=/(?<![\w:])(?:([1-3])\s+)?(?:([A-Z][a-z]+)\.?\s+)?(\d+):(\d+)(?:[-–](\d+))?(?!\d|:\d)/g;
 const AB={jn:'john',mt:'matthew',mk:'mark',lk:'luke',phil:'philippians',philem:'philemon',phlm:'philemon',jud:'jude',judg:'judges'},bk=x=>{x=x.toLowerCase();return AB[x]||x;},same=(a,b)=>{a=bk(a);b=bk(b);return a===b||(a.length>=3&&b.length>=3&&(a.startsWith(b)||b.startsWith(a)));};
 const refs=t=>{const o=[];let lb=null,ln='';for(const m of String(t).matchAll(CR)){const nb=m[2]&&!/^(?:Chapter|Verse|Round|Link|Rule|Step|Part)$/.test(m[2]);if(nb){lb=m[2];ln=m[1]||'';}else if(m[1])continue;const e={at:m.index,num:nb?(m[1]||''):ln,book:nb?m[2]:lb,c:+m[3],a:+m[4],b:+(m[5]||m[4]),txt:m[0]};o.push(e);let rest=String(t).slice(m.index+m[0].length),y;while((y=rest.match(/^(?:\s*,\s*(?:and\s+)?|\s+and\s+)(\d+)(?:[-–](\d+))?(?![\d:])/))){o.push({...e,a:+y[1],b:+(y[2]||y[1])});rest=rest.slice(y[0].length);}}return o;};
 const find=(w,t)=>{for(const r of refs(t))if(r.c===w.c&&r.a<=w.v&&w.v<=r.b&&(!r.book||!w.book||(same(r.book,w.book)&&r.num===w.num)))return r.at;return -1;};
 const VB='(?:withdraw|drop|set\\s+aside|retract)(?:\\s+(?:any|my|all)\\s+(?:reliance|rest)\\s+on)?|(?:do\\s+not|no\\s+longer)\\s+rest\\s+(?:[\\w\'’]+\\s+){0,3}?on';
 const WD=new RegExp('\\b(?:I|we)\\s+(?:(?:now|hereby|therefore|thus|also|then|so)\\s+)?(?:'+VB+')\\s+(?:(?:the\\s+)?('+LIST+')(?!\\d|:\\d)|(?:it|them)\\b)','g'),WS=new RegExp('^(?:the\\s+)?('+LIST+')\\s*(?::\\s*|\\s+(?:is|are|stays?|remains?)\\s+)(?:now\\s+)?(?:withdrawn|dropped|set\\s+aside|retracted)\\b','i');
 const PT=/\b(?:clause|phrase|words?|reading|sense|part|half|line|idiom|gloss)\b[^.;]{0,60}\b(?:in|of|from|at)\s+$/i,PART=/\b(?:by\s+(?:it|them)sel(?:f|ves)|alone|as\s+sufficient|on\s+its\s+own|of\s+itself|only\s+as)\b/i,HC=/^\s*(?:(?:and|but|even)\s+)?(?:if(?!\s+anything\b)|unless|provided|should|once(?!\s+(?:more|again|for\s+all)\b))\b/i;
 const SUB=/\b(?:if|unless|whether)\s+$|\b(?:asks?|asked|wants?|demands?|urges?|invites?|presses?)\s+(?:that\s+|me\s+to\s+)?$/i,TC=/^\s*,?\s*(?:if|unless|provided)\b/i,inQ=q=>(q.match(/(?<!\d)"/g)||[]).length%2||(q.match(/“/g)||[]).length>(q.match(/”/g)||[]).length,bare=/^\s*(?:(?:and|but|so|then|therefore|thus|hence|now)\s*,?\s*)*$/i;
 const SUP=/\b(?:(?:\w+\s+)?(layer|footing)\s+(?:of|for)|(?:stands?|rests?)\s+on)\b/i,NEG=/\b(?:do|does|did)\s+not\s+(?:rest|stand)|\bno\s+longer\b|\bset\s+aside\b|\bwithdr|\bnot\s+(?:rest|stand)/i,ATT=/\b(?:challenger|defender|opponent|other\s+side)\b[^;]*?\b(?:says?|said|claims?|argues?|holds?|asserts?|contends?)\b/i,seen=new Set(prev.map(c=>nq(c.earlier_q||'')+'|'+nq(c.closing_q||'')));
 const keep=(t,rs)=>rs.filter(r=>!PT.test(t.slice(0,r.at)));
 for(const [sd,P,r] of [['DEFENDER','CR',['cr2','cr3','cr4']],['CHALLENGER','DR',['gr2','dr3','dr4']]]){let cap=3;const W=[],own=new RegExp('\\b'+sd[0]+'(\\d)\\b'),opp=new RegExp('\\b'+(sd[0]==='D'?'C':'D')+'\\d\\b'),OS=new RegExp('\\b(?:'+(sd[0]==='D'?'challenger':'defender')+'|opponent|other\\s+side)\\b(?:(?!\\bthat\\b)[^;,])*$','i');
  const add=(i,q,rs)=>{for(const x of rs)for(let v=x.a;v<=Math.min(x.b,x.a+200);v++)W.push({round:P+(i+2),q,ref:(x.num?x.num+' ':'')+(x.book||'')+' '+x.c+':'+v,num:x.num,book:x.book,c:x.c,v});};
  r.slice(0,2).forEach((key,i)=>{const S=String(F[key]||'').split(/\n+/).flatMap(l=>l.split(SE)).map(st);S.forEach((s,x)=>{
   const z=s.match(WS);if(z)add(i,s,refs(z[1]));
   for(const m of s.matchAll(WD)){const pre=s.slice(0,m.index),tail=s.slice(m.index+m[0].length),cs=pre.split(';'),pc=cs[cs.length-1];
    if(inQ(pre)||HC.test(pc)||SUB.test(pre)||TC.test(tail)||PART.test(tail.split(/[,;]|\.\s/)[0]))continue;
    if(m[1]){let rs=refs(m[1]);if(/^\s+(?:stays|stands|remains|holds|is\s+kept)\b/.test(tail))rs=rs.slice(0,-1);add(i,s,rs);continue;}
    let rs=keep(pc,refs(pc)),q=s;
    if(!rs.length&&cs.length>1&&bare.test(pc)){const pb=cs[cs.length-2];rs=HC.test(pb)?[]:keep(pb,refs(pb));}
    else if(!rs.length&&cs.length===1&&!/["“”]/.test(pre)&&pre.trim().split(/\s+/).filter(Boolean).length<=6&&x>0){rs=keep(S[x-1],refs(S[x-1]));q=S[x-1]+' '+s;}
    add(i,q,rs);}});});
  if(!W.length)continue;let hd='?';
  for(const line of String(F[r[2]]||'').split(/\n+/)){const h=line.match(/(?:--\s*|\bLINK\s+|^[\s>#*]*)([CD])(\d)\b/)||line.match(/^[\s>#*]*LINK\s+(\d)\b/);if(h&&/^[\s>#*]*(?:#|\*\*|ANSWER|LINK|[CD]\d)/.test(line)){if(h[2]===undefined)hd=h[1];else if(h[1]===sd[0])hd=h[2];}
   const L=st(line),ss=L.split(SE);
   for(const w of W){if(cap<=0)break;if(find(w,L)<0)continue;const lead=find(w,ss[0])>=0&&ss[0].length<60;
    for(let j=0;j<ss.length;j++){if(/\?\s*$/.test(ss[j]))continue;let hit=null;for(const cl of ss[j].split(/;\s*/)){const u=cl.match(SUP);if(!u||NEG.test(cl)||ATT.test(cl.slice(0,u.index))||OS.test(cl.slice(0,u.index))||(opp.test(cl)&&!own.test(cl)))continue;
      if(u[1]?(find(w,cl)>=0||(lead&&j===1)):(()=>{const a=cl.slice(u.index+u[0].length),v=find(w,a);return v>=0&&!/\b(?:not|instead\s+of|rather\s+than)\b/i.test(a.slice(0,v));})()){hit=cl;break;}}
     if(!hit)continue;const cq=lead&&j===1?ss[0]+' '+ss[j]:ss[j],key=nq(w.q)+'|'+nq(cq);if(seen.has(key))continue;seen.add(key);cap--;
     const lm=hit.match(own);const n=lm?lm[1]:hd;
     out.push({id:'X'+(++k),side:sd,by:'the code (pkgWVR)',kind:'LINK',n,earlier_round:w.round,earlier_q:w.q,closing_round:P+'4',closing_q:cq,why:'the code found that ['+w.round+'] withdrew '+w.ref+' or stopped resting on it, and the close cites it again as a footing'+(n==='?'?' (name the link)':' of LINK '+n)+'; decide whether the close rests again on what the earlier line gave up'});break;}}}}
 return out;};
